package cn.shiying.mobile;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.media.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import cn.shiying.mobile.core.*;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** Real audio-only output, independent publication/playback/delete, and conversion failures. */
public final class NativeAudioChecks extends Instrumentation {
    int checks; Context context; MainActivity main; JSONArray created=new JSONArray(),cases=new JSONArray(); Bundle arguments;
    void check(boolean value,String description){if(!value)throw new AssertionError(description);checks++;}
    <T>T ui(Callable<T> call)throws Exception{FutureTask<T> task=new FutureTask<>(call);runOnMainSync(task);return task.get();}
    Object field(Object o,String key)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(o);}
    TextView text(View v,String label){if(v instanceof TextView&&label.equals(((TextView)v).getText().toString()))return(TextView)v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){TextView x=text(((android.view.ViewGroup)v).getChildAt(i),label);if(x!=null)return x;}return null;}
    void store(JSONObject record)throws Exception{created.put(record);JSONArray all=RecordStore.read(context);all.put(record);RecordStore.save(context,all);}
    JSONObject done(JSONObject record)throws Exception{
        long until=System.currentTimeMillis()+150000;
        while(System.currentTimeMillis()<until){long[] stats=new long[3];int state=CompoundDownloads.query(context,record,stats);JSONObject job=CompoundDownloads.job(context,record.getLong("id"));if(state==DownloadManager.STATUS_SUCCESSFUL)return CompoundDownloads.decorate(context,record);if(state==DownloadManager.STATUS_FAILED)throw new AssertionError(job.optString("error"));Thread.sleep(250);}
        throw new AssertionError("Audio job timed out");
    }
    Uri uri(JSONObject record){return Uri.parse(record.optString("localUri"));}
    void verify(JSONObject record,String name)throws Exception{
        MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(context,uri(record),null);check(extractor.getTrackCount()==1,"Exactly one audio track, no video: "+name);MediaFormat f=extractor.getTrackFormat(0);check("audio/mp4a-latm".equals(f.getString(MediaFormat.KEY_MIME)),"Playable AAC M4A: "+name);check(f.getLong(MediaFormat.KEY_DURATION)>1000000,"Actual audio duration: "+name);cases.put(new JSONObject().put("source",name).put("duration_us",f.getLong(MediaFormat.KEY_DURATION)).put("bytes",record.optLong("bytes")));}finally{extractor.release();}
        try(Cursor c=context.getContentResolver().query(uri(record),new String[]{"mime_type","relative_path","is_pending"},null,null,null)){check(c!=null&&c.moveToFirst(),"Audio is published in MediaStore");check(c.getString(0).equals("audio/mp4")&&c.getString(1).equals("Music/拾影/")&&c.getInt(2)==0,"Completed audio in Music, no pending publication");}
        check(record.optString("mime").equals("audio/mp4")&&record.optString("file").endsWith(".m4a"),"History contains a separate audio record");
        JSONArray children=CompoundDownloads.job(context,record.getLong("id")).optJSONArray("parts");for(int i=0;i<children.length();i++){long child=children.getJSONObject(i).getLong("id");try(Cursor cursor=((DownloadManager)context.getSystemService(Context.DOWNLOAD_SERVICE)).query(new DownloadManager.Query().setFilterById(child))){check(cursor==null||cursor.getCount()==0,"Temporary source downloads removed after extraction");}}
    }
    byte[] packets(Uri uri)throws Exception{MediaExtractor e=new MediaExtractor();try{e.setDataSource(context,uri,null);int track=AudioExtractor.audio(e);e.selectTrack(track);MessageDigest hash=MessageDigest.getInstance("SHA-256");ByteBuffer b=ByteBuffer.allocate(2*1024*1024);while(true){b.clear();int n=e.readSampleData(b,0);if(n<0)break;byte[] data=new byte[n];b.position(0);b.get(data);hash.update(data);if(!e.advance())break;}return hash.digest();}finally{e.release();}}
    void touch(String label)throws Exception{List<android.view.accessibility.AccessibilityNodeInfo> list=new ArrayList<>();long until=System.currentTimeMillis()+7000;while(list.isEmpty()&&System.currentTimeMillis()<until){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)list=root.findAccessibilityNodeInfosByText(label);Thread.sleep(100);}check(!list.isEmpty(),"Styled sheet exposes "+label);android.graphics.Rect b=new android.graphics.Rect();list.get(0).getBoundsInScreen(b);long now=android.os.SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(now,now,0,b.centerX(),b.centerY(),0));sendPointerSync(MotionEvent.obtain(now,now+60,1,b.centerX(),b.centerY(),0));}
    @Override public void onCreate(Bundle args){super.onCreate(args);arguments=args;start();}
    @Override public void onStart(){Bundle report=new Bundle();List<File> temporary=new ArrayList<>();int history=0,videoCount=0;
        try{
            context=getTargetContext();JSONArray original=RecordStore.read(context);history=original.length();DownloadManager dm=(DownloadManager)context.getSystemService(Context.DOWNLOAD_SERVICE);
            if(arguments!=null&&arguments.containsKey("cleanupFiles")){JSONArray names=new JSONArray(new String(android.util.Base64.decode(arguments.getString("cleanupFiles"),android.util.Base64.DEFAULT),"UTF-8"));int removed=0;for(int i=0;i<original.length();i++){JSONObject r=original.getJSONObject(i);for(int j=0;j<names.length();j++)if(r.optString("mime").startsWith("audio/")&&r.optString("file").equals(names.getString(j))){RecordDeletion.delete(context,dm,r);removed++;}}report.putString("result","Removed only explicitly named test audio files: "+removed);finish(Activity.RESULT_OK,report);return;}
            try(Cursor c=context.getContentResolver().query(android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},null,null,null)){videoCount=c.getCount();}
            main=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));VideoResolver resolver=new VideoResolver(url->android.webkit.CookieManager.getInstance().getCookie(url),s->{});
            VideoInfo info=resolver.resolve("https://v.douyin.com/xP--46iFdBs/");ui(()->{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("setVideo",VideoInfo.class);m.setAccessible(true);m.invoke(main,info);check(text(main.getWindow().getDecorView(),"▶  应用内播放")!=null,"Original video result retained");TextView audio=text(main.getWindow().getDecorView(),"提取并保存音频");check(audio!=null,"Audio output added without another URL field");audio.performClick();return null;});
            JSONObject online=null;long deadline=System.currentTimeMillis()+60000;while(System.currentTimeMillis()<deadline){JSONArray all=RecordStore.read(context);for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optString("mime").startsWith("audio/")&&r.optString("noteId").equals(info.id))online=r;}if(online!=null)break;Thread.sleep(200);}check(online!=null,"Actual audio save button creates background task");created.put(online);
            context.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));online=done(online);verify(online,"用户抖音手机分享");check(RecordStore.read(context).length()==history+1,"Audio adds exactly one independent record");
            VideoInfo bili=resolver.resolve("https://www.bilibili.com/video/BV1GJ411x7h7");List<DownloadCoordinator.Prepared> parts=DownloadCoordinator.prepareAudio(resolver,bili,bili.formats.get(0));check(parts.size()==1&&parts.get(0).asset.kind.equals("audio"),"Bili DASH audio download excludes video stream");JSONObject dash=CompoundDownloads.enqueueAudio(context,dm,bili,parts).getJSONObject(0);store(dash);dash=done(dash);verify(dash,"B站独立声音流");
            JSONObject saved=null;Uri source=null;for(int i=0;i<original.length();i++){JSONObject r=original.getJSONObject(i);if(!r.optString("mime").startsWith("video/")||!r.optString("title").contains("Rick"))continue;Uri u=r.optString("localUri").isEmpty()?dm.getUriForDownloadedFile(r.optLong("id")):Uri.parse(r.optString("localUri"));if(u!=null){saved=r;source=u;break;}}check(saved!=null,"Original downloaded video available");
            JSONObject local=CompoundDownloads.enqueueLocalAudio(context,saved,source);store(local);CompoundDownloads.schedule(context,local.getLong("id"));local=done(local);verify(local,"已有本地视频");check(Arrays.equals(packets(source),packets(uri(local))),"AAC packet content preserved without re-encoding");
            MainActivity host=main;context.startActivity(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);final JSONObject playRecord=online;ActivityMonitor monitor=addMonitor(AudioActivity.class.getName(),null,false);ui(()->{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("showRecord",JSONObject.class);m.setAccessible(true);m.invoke(host,playRecord);return null;});touch("播放音频");AudioActivity player=(AudioActivity)waitForMonitorWithTimeout(monitor,6000);removeMonitor(monitor);check(player!=null,"Audio opens private in-app player");deadline=System.currentTimeMillis()+15000;while(!ui(()->(Boolean)field(player,"ready"))&&System.currentTimeMillis()<deadline)Thread.sleep(100);check(ui(()->(Boolean)field(player,"ready")),"Audio decoder ready");Thread.sleep(500);check(ui(()->((MediaPlayer)field(player,"media")).isPlaying()),"Saved audio actually plays");ui(()->{((TextView)field(player,"play")).performClick();return null;});int paused=ui(()->((MediaPlayer)field(player,"media")).getCurrentPosition());Thread.sleep(400);check(Math.abs(ui(()->((MediaPlayer)field(player,"media")).getCurrentPosition())-paused)<150,"Audio pause holds time");ui(()->{java.lang.reflect.Method m=AudioActivity.class.getDeclaredMethod("setSpeed",float.class);m.setAccessible(true);m.invoke(player,1.5f);return null;});check(!ui(()->((MediaPlayer)field(player,"media")).isPlaying()),"Changing audio speed preserves pause");runOnMainSync(player::finish);
            File wav=new File(context.getCacheDir(),"audio-check.wav");temporary.add(wav);ByteBuffer header=ByteBuffer.allocate(44+88200).order(ByteOrder.LITTLE_ENDIAN);header.put("RIFF".getBytes("US-ASCII")).putInt(36+88200).put("WAVEfmt ".getBytes("US-ASCII")).putInt(16).putShort((short)1).putShort((short)1).putInt(22050).putInt(44100).putShort((short)2).putShort((short)16).put("data".getBytes("US-ASCII")).putInt(88200);for(int i=0;i<44100;i++)header.putShort((short)(Math.sin(i*Math.PI*2*440/22050)*5000));try(FileOutputStream out=new FileOutputStream(wav)){out.write(header.array());}
            File converted=new File(context.getCacheDir(),"audio-converted.m4a");temporary.add(converted);AudioExtractor.extract(context,-1701,Collections.singletonList(Uri.fromFile(wav)),converted);AudioExtractor.verify(converted);check(converted.length()>1000,"Non-AAC PCM is really converted to playable M4A");
            File silent=new File(context.getCacheDir(),"audio-silent.mp4");temporary.add(silent);MediaExtractor input=new MediaExtractor();input.setDataSource(context,source,null);int v=-1;for(int i=0;i<input.getTrackCount();i++)if(input.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith("video/"))v=i;MediaMuxer mux=new MediaMuxer(silent.getPath(),0);int out=mux.addTrack(input.getTrackFormat(v));input.selectTrack(v);mux.start();ByteBuffer buffer=ByteBuffer.allocate(2*1024*1024);MediaCodec.BufferInfo bi=new MediaCodec.BufferInfo();for(int i=0;i<40;i++){buffer.clear();int n=input.readSampleData(buffer,0);if(n<0)break;bi.set(0,n,input.getSampleTime(),input.getSampleFlags());mux.writeSampleData(out,buffer,bi);input.advance();}mux.stop();mux.release();input.release();
            File empty=new File(context.getCacheDir(),"audio-empty.m4a");temporary.add(empty);boolean rejected=false;try{AudioExtractor.extract(context,-1702,Collections.singletonList(Uri.fromFile(silent)),empty);}catch(Exception e){rejected=e.getMessage().contains("没有音轨");}check(rejected&&!empty.exists(),"Silent video fails clearly without a fake audio output");
            JSONObject cancel=CompoundDownloads.enqueueLocalAudio(context,saved,source);store(cancel);RecordDeletion.delete(context,dm,cancel);check(CompoundDownloads.cancelled(context,cancel.getLong("id")),"Cancelling audio stops its job");check(!CompoundDownloads.complete(context,cancel.getLong("id"),"content://media/fake",4),"Cancelled audio cannot reappear from late completion");
            try(Cursor c=context.getContentResolver().query(android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},null,null,null)){check(c.getCount()==videoCount,"Audio operations preserve video gallery");}
            for(int i=0;i<created.length();i++){JSONObject r=created.getJSONObject(i);Uri u=uri(CompoundDownloads.decorate(context,r));RecordDeletion.delete(context,dm,r);if(!u.toString().isEmpty())try(Cursor c=context.getContentResolver().query(u,new String[]{"_id"},null,null,null)){check(c==null||c.getCount()==0,"Deleted audio removed from music collection");}}
            check(RecordStore.read(context).length()==history,"Original history retained after test audio cleanup");report.putString("result","PASS: real audio-only M4A, native AAC preservation/PCM conversion, background completion, Bili sound-only source, internal play/pause/speed, music publication, deletion and cancel tombstones");report.putInt("checks",checks);report.putString("cases",cases.toString());report.putString("scope","Dedicated Android 15 emulator; supplied Douyin link, real Bili audio and existing local video, controlled PCM/silent cases; no physical phone");finish(Activity.RESULT_OK,report);
        }catch(Throwable error){report.putString("error",error.toString());report.putInt("checks",checks);report.putString("cases",cases.toString());finish(Activity.RESULT_CANCELED,report);}
        finally{if(context!=null)for(int i=0;i<created.length();i++)try{RecordDeletion.delete(context,(DownloadManager)context.getSystemService(Context.DOWNLOAD_SERVICE),created.getJSONObject(i));}catch(Exception ignored){}for(File f:temporary)f.delete();}
    }
}
